CREATE TABLE projects(id TEXT PRIMARY KEY,title TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','paused','archived')),created_at TEXT NOT NULL);
CREATE TABLE sessions(id TEXT PRIMARY KEY,tool TEXT NOT NULL CHECK(tool IN ('codex','claude-code','antigravity','opencode','other')),label TEXT NOT NULL,capabilities_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('available','busy','closed')),created_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,lease_until TEXT NOT NULL);
CREATE TABLE memberships(session_id TEXT NOT NULL REFERENCES sessions(id),project_id TEXT NOT NULL REFERENCES projects(id),role TEXT NOT NULL CHECK(role IN ('worker','reviewer','leader-candidate','integrator')),PRIMARY KEY(session_id,project_id,role));
CREATE TABLE leader_leases(project_id TEXT PRIMARY KEY REFERENCES projects(id),session_id TEXT NOT NULL REFERENCES sessions(id),generation INTEGER NOT NULL,lease_until TEXT NOT NULL);
CREATE TABLE tasks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),request_id TEXT UNIQUE,title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,priority INTEGER NOT NULL CHECK(priority BETWEEN 0 AND 100),required_capabilities_json TEXT NOT NULL,outputs_json TEXT NOT NULL,acceptance_json TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('proposed','ready','claimed','in_progress','submitted','in_review','completed','blocked','rejected','cancelled')),version INTEGER NOT NULL,current_attempt_id TEXT REFERENCES attempts(id),reservation_session_id TEXT REFERENCES sessions(id),reservation_until TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE dependencies(task_id TEXT NOT NULL REFERENCES tasks(id),depends_on_id TEXT NOT NULL REFERENCES tasks(id),PRIMARY KEY(task_id,depends_on_id));
CREATE TABLE attempts(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),session_id TEXT NOT NULL REFERENCES sessions(id),generation INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('claimed','in_progress','submitted','accepted','revision','rejected','abandoned')),lease_until TEXT NOT NULL,checkpoint_json TEXT NOT NULL,manifest_json TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(task_id,generation));
CREATE TABLE reviews(id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES attempts(id),reviewer_session_id TEXT NOT NULL REFERENCES sessions(id),outcome TEXT NOT NULL CHECK(outcome IN ('accepted','revision','rejected','blocked')),evidence TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE recommendations(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),session_id TEXT NOT NULL REFERENCES sessions(id),task_id TEXT REFERENCES tasks(id),dedupe_key TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('proposed','accepted','declined','deferred')),created_at TEXT NOT NULL,UNIQUE(project_id,dedupe_key));
CREATE TABLE imports(request_id TEXT PRIMARY KEY,sha256 TEXT NOT NULL,source_path TEXT NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id));
CREATE TABLE events(seq INTEGER PRIMARY KEY AUTOINCREMENT,event_id TEXT NOT NULL UNIQUE,at TEXT NOT NULL,session_id TEXT REFERENCES sessions(id),project_id TEXT REFERENCES projects(id),task_id TEXT REFERENCES tasks(id),action TEXT NOT NULL,result TEXT NOT NULL,payload_json TEXT NOT NULL);
CREATE TABLE operations(op_id TEXT PRIMARY KEY,command TEXT NOT NULL,input_hash TEXT NOT NULL,response_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'events are append-only'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'events are append-only'); END;
CREATE TABLE appointments(code_hash TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),role TEXT NOT NULL CHECK(role IN ('leader','reviewer','integrator','worker')),created_at TEXT NOT NULL,expires_at TEXT NOT NULL,redeemed_by TEXT REFERENCES sessions(id),redeemed_at TEXT);
CREATE TABLE project_git(project_id TEXT PRIMARY KEY REFERENCES projects(id),repository TEXT NOT NULL,base_branch TEXT NOT NULL,set_at TEXT NOT NULL);
CREATE TABLE attempt_git(attempt_id TEXT PRIMARY KEY REFERENCES attempts(id),start_ref TEXT NOT NULL,base_sha TEXT,head_sha TEXT,submitted_at TEXT);
CREATE TABLE integrations(task_id TEXT PRIMARY KEY REFERENCES tasks(id),attempt_id TEXT NOT NULL REFERENCES attempts(id),head_sha TEXT,merge_sha TEXT,destination TEXT NOT NULL,evidence TEXT,session_id TEXT REFERENCES sessions(id),at TEXT NOT NULL);
CREATE TABLE session_hosts(session_id TEXT PRIMARY KEY REFERENCES sessions(id),name TEXT NOT NULL,pid INTEGER NOT NULL,started TEXT NOT NULL,seen_at TEXT NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),from_session_id TEXT REFERENCES sessions(id),to_session_id TEXT REFERENCES sessions(id),to_role TEXT,task_id TEXT REFERENCES tasks(id),body TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT);
CREATE TABLE project_flags(project_id TEXT NOT NULL REFERENCES projects(id),name TEXT NOT NULL,value TEXT NOT NULL,set_at TEXT NOT NULL,PRIMARY KEY(project_id,name));
CREATE INDEX events_project_action ON events(project_id,action,seq);
CREATE INDEX tasks_project_state ON tasks(project_id,state,priority);
CREATE INDEX attempts_session_state ON attempts(session_id,state);
CREATE INDEX messages_to ON messages(project_id,to_session_id,read_at);
PRAGMA user_version=2;
